function postsMarkup(posts, pinned = false) {
  if (pinned && !posts.length) return "";
  return `<section id="${pinned ? "pinned-news" : "news"}" class="wrap news-section${pinned ? " pinned-news" : ""}"><div class="section-heading"><div><div class="eyebrow">${pinned ? "\u0645\u062E\u062A\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u0631\u0643\u0632" : "\u0627\u0644\u0645\u0646\u0634\u0648\u0631\u0627\u062A \u0627\u0644\u062A\u0639\u0644\u064A\u0645\u064A\u0629"}</div><h2>${pinned ? "\u0645\u0646\u0634\u0648\u0631\u0627\u062A \u0645\u062B\u0628\u062A\u0629" : "\u062C\u062F\u064A\u062F \u0627\u0644\u0645\u0631\u0643\u0632"}</h2></div></div>${posts.length ? `<div class="news-grid">${posts.map((p) => `<article class="news-card${pinned ? " pinned-post" : ""}">${pinned ? '<span class="pinned-label">\u0645\u0646\u0634\u0648\u0631 \u0645\u062B\u0628\u062A</span>' : ""}${p.image ? `<img src="${esc2(p.image)}" alt="${esc2(p.title)}" loading="lazy">` : ""}<div><h3><a href="/news/${esc2(p.slug)}/">${esc2(p.title)}</a></h3><p>${esc2(p.summary)}</p><a class="btn outline" href="/news/${esc2(p.slug)}/">\u0627\u0642\u0631\u0623 \u0627\u0644\u0645\u0646\u0634\u0648\u0631</a></div></article>`).join("")}</div>` : '<div class="reviews-empty"><strong>\u0633\u062A\u0638\u0647\u0631 \u0627\u0644\u0645\u0646\u0634\u0648\u0631\u0627\u062A \u0627\u0644\u062A\u0639\u0644\u064A\u0645\u064A\u0629 \u0647\u0646\u0627.</strong><p>\u0639\u0646\u062F \u0646\u0634\u0631 \u0623\u064A \u0645\u0646\u0634\u0648\u0631 \u0645\u0646 \u0644\u0648\u062D\u0629 \u0627\u0644\u062A\u062D\u0643\u0645 \u0633\u064A\u0638\u0647\u0631 \u0641\u064A \u0647\u0630\u0627 \u0627\u0644\u0642\u0633\u0645 \u062A\u0644\u0642\u0627\u0626\u064A\u064B\u0627.</p></div>'}</section>`;
}
function postPage(p, admin, env, presentation) {
  const url = ORIGIN + "/news/" + p.slug + "/";
  return page({ title: p.title + " | " + seo_default.siteName, description: p.summary, path: "/news/" + p.slug + "/", socialImage: p.image || null, socialType: "article", body: `<main id="main" class="wrap post-page"><a href="/">\u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629</a><h1>${esc2(p.title)}</h1><p class="description">${esc2(p.summary)}</p>${p.image ? `<img class="post-image" src="${esc2(p.image)}" alt="${esc2(p.title)}">` : ""}<div class="post-body">${esc2(p.body).replace(/\n/g, "<br>")}</div></main>`, schema: [businessSchema(presentation), { "@context": "https://schema.org", "@type": "Article", "@id": url + "#article", url, mainEntityOfPage: url, headline: p.title, description: p.summary, datePublished: p.published_at, dateModified: p.updated_at, image: p.image ? [new URL(p.image, ORIGIN).href] : [], author: { "@id": ORIGIN + "/#store" }, publisher: { "@id": ORIGIN + "/#store" } }], admin, env });
}
function errorPage(message, status, env = {}) {
  return page({ title: status === 404 ? "\u0627\u0644\u0635\u0641\u062D\u0629 \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F\u0629 | \u0623\u0628\u0648 \u0645\u0635\u0637\u0641\u0649" : "\u062A\u0639\u0630\u0651\u0631 \u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0637\u0644\u0628 | \u0623\u0628\u0648 \u0645\u0635\u0637\u0641\u0649", description: message, body: `<main id="main" class="wrap detail-page" style="padding-block:80px"><div class="eyebrow">\u0645\u0631\u0643\u0632 \u0623\u0628\u0648 \u0645\u0635\u0637\u0641\u0649 \u0627\u0644\u062A\u062C\u0627\u0631\u064A</div><h1>${status === 404 ? "\u0644\u0645 \u0646\u0639\u062F \u0646\u0639\u0631\u0636 \u0647\u0630\u0627 \u0627\u0644\u0645\u0646\u062A\u062C." : "\u062A\u0639\u0630\u0651\u0631 \u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0637\u0644\u0628 \u0627\u0644\u0622\u0646."}</h1><p style="margin:24px 0">${esc2(message)}</p><a class="btn" href="/#catalog">\u0627\u0644\u0639\u0648\u062F\u0629 \u0625\u0644\u0649 \u0627\u0644\u062A\u0634\u0643\u064A\u0644\u0629</a> ${ext(WA, "\u062A\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627", "btn whatsapp", "whatsapp")}</main>`, env, manage: false, noIndex: true, path: null });
}
